from pathlib import Path
p=Path('smeny_pro_mobile_build/www/index.html')
s=p.read_text(encoding='utf-8')
repls=[
('<button data-page="absences"><span class="ico">◷</span>Absence a volno</button><button data-page="reports">','<button data-page="absences"><span class="ico">◷</span>Absence a volno</button><button data-page="swaps"><span class="ico">⇄</span>Výměna směn</button><button data-page="reports">'),
('<button onclick="nav(\'reports\');closeMobileMore()"><span>▥</span>Statistiky</button>','<button onclick="nav(\'swaps\');closeMobileMore()"><span>⇄</span>Výměna směn</button><button onclick="nav(\'reports\');closeMobileMore()"><span>▥</span>Statistiky</button>'),
('absences:[],assignments:[],rules:','absences:[],assignments:[],swaps:[],rules:'),
('db.rules={...defaults.rules,...db.rules};db.settings={...defaults.settings,...db.settings}','db.rules={...defaults.rules,...db.rules};db.settings={...defaults.settings,...db.settings};db.swaps=Array.isArray(db.swaps)?db.swaps:[]'),
("settings:'Nastavení vzhledu'})[page]","settings:'Nastavení vzhledu',swaps:'Výměna směn'})[page]"),
("if(page==='absences')v.innerHTML=absencesPage();if(page==='reports')","if(page==='absences')v.innerHTML=absencesPage();if(page==='swaps')v.innerHTML=swapsPage();if(page==='reports')")]
for old,new in repls:
 if old not in s: raise SystemExit('Expected fragment missing: '+old[:55])
 s=s.replace(old,new,1)
if 'function swapsPage()' not in s:
 js=r"""
function swapLabel(a){return fmt(a.date)+' · '+(a.type==='D'?'Denní':'Noční')+' '+a.start+'–'+a.end+' · '+empName(a.employeeId)}
function swapCheck(eid,sh,ignore){let e=db.employees.find(x=>x.id===eid);if(!e||e.active===false)return 'Zaměstnanec není aktivní.';if((e.onlyDay&&sh.type==='N')||(e.onlyNight&&sh.type==='D'))return 'Nesouhlasí omezení denní/noční.';if(e.weekdays&&[0,6].includes(new Date(sh.date+'T12:00:00').getDay()))return 'Zaměstnanec může pracovat jen Po–Pá.';if(e.positions?.length&&!e.positions.includes(sh.positionId))return 'Chybí kvalifikace.';if(db.positions.find(p=>p.id===sh.positionId)?.lead&&!e.isLead)return 'Směna vyžaduje vedoucího.';if(db.absences.some(a=>a.employeeId===eid&&a.status!=='zamítnuto'&&a.from<=sh.date&&a.to>=sh.date))return 'V termínu je absence.';let arr=db.assignments.filter(a=>a.employeeId===eid&&!ignore.includes(a.id));if(arr.some(a=>a.date===sh.date))return 'V tento den už má jinou směnu.';arr.push(sh);arr.sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start));let prev=null,streak=0;for(let a of arr){if(prev&&prev.date===a.date)continue;let gap=prev?(new Date(a.date+'T12:00:00')-new Date(prev.date+'T12:00:00'))/86400000:99;streak=gap===1?streak+1:1;if(streak>(e.maxConsecutive||db.rules.maxConsecutive||4))return 'Překročen limit směn za sebou.';if(prev){let mins=t=>+t.slice(0,2)*60+(+t.slice(3));let rest=(gap*1440+mins(a.start)-mins(prev.start)-duration(prev.start,prev.end)*60)/60;if(rest<(db.rules.minRest||0))return 'Nedostatečný odpočinek.';if(prev.type==='N'&&a.type==='D'&&db.rules.avoidNightToDay)return 'Zakázaný přechod noční–denní.'}prev=a}let next=arr.find(a=>a.date>sh.date);if(next){let dg=(new Date(next.date+'T12:00:00')-new Date(sh.date+'T12:00:00'))/86400000;let mins=t=>+t.slice(0,2)*60+(+t.slice(3));let rest=(dg*1440+mins(next.start)-mins(sh.start)-duration(sh.start,sh.end)*60)/60;if(rest<(db.rules.minRest||0))return 'Nedostatečný odpočinek před další směnou.';if(sh.type==='N'&&next.type==='D'&&db.rules.avoidNightToDay)return 'Vytvořil by se přechod noční–denní.'}let hrs=arr.filter(a=>a.date.startsWith(sh.date.slice(0,7))).reduce((n,a)=>n+duration(a.start,a.end),0),cap=e.maxHours||db.rules.maxHours;if(cap>0&&hrs>cap)return 'Překročen měsíční limit hodin.';for(let pair of db.rules.excludePairs||[]){let other=pair.find(x=>x!==eid&&pair.includes(eid));if(other&&db.assignments.some(a=>a.employeeId===other&&a.date===sh.date&&!ignore.includes(a.id)))return 'Porušila by se zakázaná dvojice.'}return ''}
function swapsPage(){let pending=db.swaps.filter(x=>x.status==='čeká na schválení'),done=db.swaps.filter(x=>x.status!=='čeká na schválení');let card=x=>{let a=db.assignments.find(z=>z.id===x.a),b=db.assignments.find(z=>z.id===x.b);return '<div class="rulebox" style="margin-bottom:10px"><b>'+esc(x.by)+'</b> · <span class="pill warn">'+esc(x.status)+'</span><p class="small">'+(a?esc(swapLabel(a)):'Směna nenalezena')+'<br>⇄<br>'+(b?esc(swapLabel(b)):'Směna nenalezena')+'</p>'+(x.note?'<p class="small muted">'+esc(x.note)+'</p>':'')+(x.status==='čeká na schválení'?'<button class="primary" onclick="approveSwap(\''+x.id+'\')">Schválit výměnu</button> <button class="danger" onclick="rejectSwap(\''+x.id+'\')">Zamítnout</button>':'')+'</div>'};return pageHead('Výměna směn','Žádosti o vzájemnou výměnu naplánovaných směn','<button class="primary" onclick="newSwap()">＋ Navrhnout výměnu</button>')+'<div class="notice">Směny se prohodí až po schválení. Ověřuje se dostupnost, kvalifikace, absence, odpočinek a limity.</div><div class="card"><h2>Čekající žádosti ('+pending.length+')</h2>'+(pending.length?pending.map(card).join(''):'<div class="empty">Žádné čekající žádosti.</div>')+'</div><div class="card"><h2>Historie</h2>'+(done.length?done.slice().reverse().map(card).join(''):'<div class="empty">Zatím bez historie.</div>')+'</div>'}
function newSwap(){let shifts=db.assignments.filter(a=>db.employees.some(e=>e.id===a.employeeId&&e.active!==false));if(shifts.length<2){toast('Nejsou naplánované alespoň dvě směny.');return}let opts=shifts.map(a=>'<option value="'+a.id+'">'+esc(swapLabel(a))+'</option>').join('');showModal('Navrhnout výměnu','<form id="swapForm" class="formgrid"><div class="field full"><label>První směna</label><select name="a">'+opts+'</select></div><div class="field full"><label>Druhá směna</label><select name="b">'+opts+'</select></div><div class="field full"><label>Poznámka</label><textarea name="note" maxlength="300"></textarea></div></form>',()=>{let f=$('#swapForm'),a=db.assignments.find(z=>z.id===f.a.value),b=db.assignments.find(z=>z.id===f.b.value);if(!a||!b||a.id===b.id||a.employeeId===b.employeeId){toast('Vyber dvě různé směny dvou zaměstnanců.');return}if(db.swaps.some(x=>x.status==='čeká na schválení'&&[x.a,x.b].some(id=>id===a.id||id===b.id))){toast('Jedna směna už čeká na výměnu.');return}let q={id:uid(),a:a.id,b:b.id,by:empName(a.employeeId),status:'čeká na schválení',note:f.note.value.trim()};db.swaps.push(q);if(!save()){db.swaps.pop();return}closeModal();render('swaps');toast('Žádost uložena.')})}
function approveSwap(id){let q=db.swaps.find(x=>x.id===id),a=db.assignments.find(x=>x.id===q?.a),b=db.assignments.find(x=>x.id===q?.b);if(!q||q.status!=='čeká na schválení')return;if(!a||!b){toast('Některá směna už neexistuje.');return}let e1=swapCheck(b.employeeId,a,[a.id,b.id]),e2=swapCheck(a.employeeId,b,[a.id,b.id]);if(e1||e2){showModal('Výměnu nelze schválit','<div class="notice">'+(e1?esc(empName(b.employeeId)+': '+e1)+'<br>':'')+(e2?esc(empName(a.employeeId)+': '+e2):'')+'</div>',null,'<button class="primary" onclick="closeModal()">Zavřít</button>');return}let x=a.employeeId,y=b.employeeId;a.employeeId=y;b.employeeId=x;q.status='schváleno';if(!save()){a.employeeId=x;b.employeeId=y;q.status='čeká na schválení';return}render('swaps');toast('Výměna schválena a rozpis změněn.')}
function rejectSwap(id){let q=db.swaps.find(x=>x.id===id);if(!q||q.status!=='čeká na schválení')return;q.status='zamítnuto';save();render('swaps');toast('Žádost zamítnuta.')}
"""
 s=s.replace('function settingsPage(){',js+'\nfunction settingsPage(){',1)
p.write_text(s,encoding='utf-8')
print('Phase 2: shift exchange workflow added.')
